import { useState, useMemo, useRef, useEffect } from 'react'
import { calcSnowDrift } from '../engines/snowDrift'
import UnitInput from '../components/shared/UnitInput'
import ResultBox from '../components/shared/ResultBox'

export default function SnowDrift() {
  const [pg, setPg] = useState('30')
  const [ps, setPs] = useState('20')
  const [lu, setLu] = useState('60')
  const [ll, setLl] = useState('40')
  const [hr, setHr] = useState('5')
  const canvasRef = useRef(null)

  const result = useMemo(() => calcSnowDrift({
    pg: parseFloat(pg) || 0,
    ps: parseFloat(ps) || 0,
    lu: parseFloat(lu) || 0,
    ll: parseFloat(ll) || 0,
    hr: parseFloat(hr) || 0,
  }), [pg, ps, lu, ll, hr])

  useEffect(() => {
    if (!canvasRef.current || !result) return
    drawDiagram(canvasRef.current, result, parseFloat(ps) || 0, parseFloat(lu) || 0)
  }, [result, ps, lu])

  return (
    <div>
      <h3 style={titleStyle}>SNOW DRIFT LOAD</h3>
      <p style={descStyle}>ASCE 7-10 §7.7 (Leeward) / §7.8 (Windward) — US Customary (psf, ft)</p>

      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-4 mb-6">
        <UnitInput id="sd-pg" label="Ground Snow pg" unit="psf" value={pg} onChange={setPg} />
        <UnitInput id="sd-ps" label="Roof Snow ps"   unit="psf" value={ps} onChange={setPs} />
        <UnitInput id="sd-lu" label="Upper Length lu" unit="ft"  value={lu} onChange={setLu} />
        <UnitInput id="sd-ll" label="Lower Length ll" unit="ft"  value={ll} onChange={setLl} />
        <UnitInput id="sd-hr" label="Step Height hr"  unit="ft"  value={hr} onChange={setHr} />
      </div>

      {result && (
        <>
          <div style={{
            padding: '10px 16px', borderRadius: 8, marginBottom: 16,
            background: result.applicable ? 'rgba(74,222,128,0.08)' : 'rgba(90,99,122,0.15)',
            border: `1px solid ${result.applicable ? 'var(--val-pos)' : 'var(--bd-subtle)'}`,
            fontSize: 13, color: result.applicable ? 'var(--val-pos)' : 'var(--tx-muted)',
          }}>
            {result.applicable
              ? `✅ Snow drift applicable — hc/hb = ${result.ratio.toFixed(2)} ≥ 0.2`
              : `⛔ Snow drift not required — hc/hb = ${result.ratio.toFixed(2)} < 0.2 (ASCE 7-10 §7.7)`
            }
          </div>

          <div className="grid md:grid-cols-3 gap-4 mb-6">
            <InfoRow label="Snow Density γ"       val={`${result.gamma.toFixed(2)} pcf`} />
            <InfoRow label="Balanced Snow Depth hb" val={`${result.hb.toFixed(3)} ft`} />
            <InfoRow label="Effective Height hc"    val={`${result.hc.toFixed(3)} ft`} />
          </div>

          {result.applicable && result.governing && (
            <div className="grid md:grid-cols-2 gap-6">
              <DriftTable label="Leeward Drift" data={result.leeward} hdRaw={result.hdLeeward} />
              <DriftTable label="Windward Drift" data={result.windward} hdRaw={result.hdWindward} />
            </div>
          )}

          {result.applicable && result.governing && (
            <ResultBox title="Governing Design Values" accent>
              <div style={{ display: 'flex', gap: 32 }}>
                <p>hd = <b style={{ color: 'var(--val-pos)' }}>{result.governing.hd.toFixed(2)} ft</b></p>
                <p>w = <b style={{ color: 'var(--val-pos)' }}>{result.governing.w.toFixed(2)} ft</b></p>
                <p>p_max = <b style={{ color: 'var(--val-pos)' }}>{result.governing.pmax.toFixed(2)} psf</b>
                  <span style={{ fontSize: 11, color: 'var(--tx-muted)', marginLeft: 8 }}>
                    ({(result.governing.pmax * 0.04788).toFixed(3)} kPa)
                  </span>
                </p>
              </div>
            </ResultBox>
          )}

          <canvas ref={canvasRef} width={700} height={240}
            style={{ marginTop: 20, borderRadius: 8, background: 'var(--bg-inset)', maxWidth: '100%' }} />
        </>
      )}
    </div>
  )
}

function InfoRow({ label, val }) {
  return (
    <div style={{ background: 'var(--bg-card)', border: '1px solid var(--bd-subtle)', borderRadius: 8, padding: '10px 14px' }}>
      <div style={{ fontSize: 11, color: 'var(--tx-secondary)', marginBottom: 4 }}>{label}</div>
      <div style={{ fontWeight: 700, color: 'var(--ac-main)' }}>{val}</div>
    </div>
  )
}

function DriftTable({ label, data, hdRaw }) {
  if (!data) return (
    <div style={{ background: 'var(--bg-card)', border: '1px solid var(--bd-subtle)', borderRadius: 8, padding: 14 }}>
      <h4 style={{ fontSize: 12, fontWeight: 700, color: 'var(--tx-secondary)', marginBottom: 8 }}>{label}</h4>
      <p style={{ color: 'var(--tx-muted)', fontSize: 12 }}>N/A (hd ≤ 0)</p>
    </div>
  )
  return (
    <div style={{ background: 'var(--bg-card)', border: '1px solid var(--bd-subtle)', borderRadius: 8, padding: 14 }}>
      <h4 style={{ fontSize: 12, fontWeight: 700, color: 'var(--ac-main)', marginBottom: 10 }}>{label}</h4>
      {[
        ['hd (calc.)',  `${hdRaw.toFixed(3)} ft`],
        ['hd (applied)', `${data.hd.toFixed(3)} ft${data.capped ? ' ← capped by hc' : ''}`],
        ['Width w',    `${data.w.toFixed(2)} ft / ${(data.w * 0.3048).toFixed(2)} m`],
        ['Drift load pd',  `${data.pd.toFixed(2)} psf / ${(data.pd * 0.04788).toFixed(3)} kPa`],
        ['Max load pmax',  `${data.pmax.toFixed(2)} psf / ${(data.pmax * 0.04788).toFixed(3)} kPa`],
      ].map(([l, v]) => (
        <div key={l} style={{ display: 'flex', justifyContent: 'space-between', padding: '4px 0', fontSize: 12, borderBottom: '1px solid var(--bd-subtle)' }}>
          <span style={{ color: 'var(--tx-secondary)' }}>{l}</span>
          <span style={{ fontWeight: 600, color: 'var(--tx-primary)' }}>{v}</span>
        </div>
      ))}
    </div>
  )
}

function drawDiagram(canvas, result, ps, lu) {
  const ctx = canvas.getContext('2d')
  ctx.clearRect(0, 0, canvas.width, canvas.height)

  const W = canvas.width, H = canvas.height
  const pad   = 30
  const wallW = 12

  // ── 3-equal horizontal sections ─────────────────────────────
  const totalW   = W - 2 * pad
  const secW     = totalW / 3          // width of each section
  const leftWallX  = pad + secW        // boundary windward | upper
  const rightWallX = pad + 2 * secW    // boundary upper | leeward

  const lowerY = H * 0.64
  const upperY = H * 0.30

  if (!result?.applicable || !result.governing) {
    ctx.strokeStyle = '#455a64'; ctx.lineWidth = 2
    drawOutline(ctx, pad, leftWallX, rightWallX, W, lowerY, upperY, wallW)
    ctx.fillStyle = '#546e7a'; ctx.font = '12px Inter,Arial'
    ctx.fillText('Snow drift not applicable (hc/hb < 0.2)', pad + 10, (lowerY + upperY) / 2)
    return
  }

  ctx.strokeStyle = '#26c6da'; ctx.lineWidth = 2
  drawOutline(ctx, pad, leftWallX, rightWallX, W, lowerY, upperY, wallW)

  const psDepth   = 8
  const maxDriftPx = lowerY - upperY - 20
  const gov = result.governing
  const scaleH = maxDriftPx / Math.max(gov.hd, 0.1)

  // ── Balanced snow on UPPER roof ────────────────────────────
  ctx.fillStyle = 'rgba(251,191,36,0.20)'
  ctx.fillRect(leftWallX, upperY - psDepth, secW, psDepth)
  ctx.fillStyle = '#ffd54f'; ctx.font = 'bold 10px Inter,Arial'
  const upMid = leftWallX + secW / 2
  ctx.fillText(`ps = ${ps} psf`, upMid - 30, upperY - psDepth - 3)

  // ── WINDWARD section (left) ───────────────────────────────
  {
    ctx.fillStyle = 'rgba(251,191,36,0.15)'
    ctx.fillRect(pad, lowerY - psDepth, secW - wallW / 2, psDepth)

    if (result.windward) {
      const wd  = result.windward
      const dH  = Math.min(wd.hd * scaleH, lowerY - upperY - 10)
      const dW  = Math.min(wd.w * (secW / Math.max(wd.w, 1)), secW - wallW / 2)
      const wallRX = leftWallX - wallW / 2

      ctx.fillStyle = 'rgba(38,198,218,0.35)'
      ctx.beginPath()
      ctx.moveTo(wallRX, lowerY)
      ctx.lineTo(wallRX - dW, lowerY)
      ctx.lineTo(wallRX, lowerY - dH)
      ctx.closePath()
      ctx.fill()
      ctx.strokeStyle = '#26c6da'; ctx.lineWidth = 1.5; ctx.stroke()

      ctx.fillStyle = '#90caf9'; ctx.font = 'bold 9px Inter,Arial'
      ctx.fillText(`pd=${wd.pd.toFixed(1)}psf`, Math.max(pad + 2, wallRX - dW + 2), lowerY - dH - 3)
      ctx.fillStyle = '#90caf9aa'; ctx.font = '9px Inter,Arial'
      ctx.fillText(`hd=${wd.hd.toFixed(2)}ft`, wallRX + 3, lowerY - dH / 2)
      ctx.fillText(`w=${wd.w.toFixed(1)}ft`, wallRX - dW / 2 - 14, lowerY + 12)
    }

    const wMid = pad + secW / 2
    ctx.fillStyle = '#90caf9'; ctx.font = 'bold 11px Inter,Arial'
    ctx.fillText('WINDWARD', wMid - 32, lowerY + 26)
    ctx.fillStyle = '#90caf9aa'; ctx.font = '9px Inter,Arial'
    ctx.fillText(`ps=${ps}psf`, pad + 4, lowerY - psDepth - 3)
  }

  // ── UPPER ROOF section labels ─────────────────────────────
  ctx.fillStyle = '#90caf9'; ctx.font = 'bold 10px Inter,Arial'
  ctx.fillText('UPPER ROOF', upMid - 30, upperY + 14)
  ctx.fillStyle = '#90caf9aa'; ctx.font = '9px Inter,Arial'
  ctx.fillText(`lu = ${lu} ft`, upMid - 18, upperY + 26)

  // ── LEEWARD section (right) ────────────────────────────────
  {
    ctx.fillStyle = 'rgba(251,191,36,0.15)'
    ctx.fillRect(rightWallX + wallW / 2, lowerY - psDepth, secW - wallW / 2, psDepth)

    const ld = result.leeward ?? result.governing
    if (ld) {
      const dH   = Math.min(ld.hd * scaleH, lowerY - upperY - 10)
      const dW   = Math.min(ld.w * (secW / Math.max(ld.w, 1)), secW - wallW / 2)
      const wallLX = rightWallX + wallW / 2

      ctx.fillStyle = 'rgba(38,198,218,0.35)'
      ctx.beginPath()
      ctx.moveTo(wallLX, lowerY)
      ctx.lineTo(wallLX + dW, lowerY)
      ctx.lineTo(wallLX, lowerY - dH)
      ctx.closePath()
      ctx.fill()
      ctx.strokeStyle = '#26c6da'; ctx.lineWidth = 1.5; ctx.stroke()

      ctx.fillStyle = '#e8eaf6'; ctx.font = 'bold 9px Inter,Arial'
      ctx.fillText(`pd=${ld.pd.toFixed(1)}psf`, wallLX + 2, lowerY - dH - 3)
      ctx.fillStyle = '#e8eaf6aa'; ctx.font = '9px Inter,Arial'
      ctx.fillText(`hd=${ld.hd.toFixed(2)}ft`, wallLX + 2, lowerY - dH / 2)
      ctx.fillText(`w=${ld.w.toFixed(1)}ft`, wallLX + dW / 2 - 10, lowerY + 12)
    }

    const lMid = rightWallX + secW / 2
    ctx.fillStyle = '#e8eaf6'; ctx.font = 'bold 11px Inter,Arial'
    ctx.fillText('LEEWARD', lMid - 28, lowerY + 26)
    ctx.fillStyle = '#e8eaf6aa'; ctx.font = '9px Inter,Arial'
    ctx.fillText(`ps=${ps}psf`, W - pad - 56, lowerY - psDepth - 3)
  }

  // ── Wind arrow ────────────────────────────────────────────
  const arrowY = 18
  ctx.strokeStyle = '#ffd54f'; ctx.lineWidth = 2
  ctx.beginPath(); ctx.moveTo(pad, arrowY); ctx.lineTo(leftWallX - 20, arrowY); ctx.stroke()
  ctx.fillStyle = '#ffd54f'
  ctx.beginPath(); ctx.moveTo(leftWallX - 8, arrowY); ctx.lineTo(leftWallX - 22, arrowY - 5); ctx.lineTo(leftWallX - 22, arrowY + 5); ctx.closePath(); ctx.fill()
  ctx.fillStyle = '#ffd54f'; ctx.font = 'bold 10px Inter,Arial'
  ctx.fillText('WIND →', pad, arrowY - 4)

  // ── Section divider lines ─────────────────────────────────
  ctx.setLineDash([4, 4])
  ctx.strokeStyle = '#37474f'; ctx.lineWidth = 1
  ctx.beginPath(); ctx.moveTo(leftWallX, 0); ctx.lineTo(leftWallX, upperY - 2); ctx.stroke()
  ctx.beginPath(); ctx.moveTo(rightWallX, 0); ctx.lineTo(rightWallX, upperY - 2); ctx.stroke()
  ctx.setLineDash([])
}

function drawOutline(ctx, pad, leftWallX, rightWallX, W, lowerY, upperY, wallW) {
  // Windward lower roof
  ctx.beginPath(); ctx.moveTo(pad, lowerY); ctx.lineTo(leftWallX - wallW / 2, lowerY); ctx.stroke()
  // Upper roof
  ctx.beginPath(); ctx.moveTo(leftWallX - wallW / 2, upperY); ctx.lineTo(rightWallX + wallW / 2, upperY); ctx.stroke()
  // Leeward lower roof
  ctx.beginPath(); ctx.moveTo(rightWallX + wallW / 2, lowerY); ctx.lineTo(W - pad, lowerY); ctx.stroke()
  // Left step wall
  ctx.beginPath(); ctx.moveTo(leftWallX - wallW / 2, lowerY); ctx.lineTo(leftWallX - wallW / 2, upperY); ctx.stroke()
  ctx.beginPath(); ctx.moveTo(leftWallX + wallW / 2, lowerY); ctx.lineTo(leftWallX + wallW / 2, upperY); ctx.stroke()
  // Right step wall
  ctx.beginPath(); ctx.moveTo(rightWallX - wallW / 2, lowerY); ctx.lineTo(rightWallX - wallW / 2, upperY); ctx.stroke()
  ctx.beginPath(); ctx.moveTo(rightWallX + wallW / 2, lowerY); ctx.lineTo(rightWallX + wallW / 2, upperY); ctx.stroke()
}

const titleStyle = { fontSize: '1.3rem', fontWeight: 700, marginBottom: 8, color: 'var(--tx-primary)', paddingBottom: 10, borderBottom: '1px solid var(--bd-subtle)' }
const descStyle  = { marginBottom: 20, color: 'var(--tx-secondary)', fontSize: 13 }
