/**
 * Snow Drift Load 계산
 * ASCE 7-10 §7.7 (Leeward) / §7.8 (Windward)
 * 입출력 단위: US Customary (psf, ft)
 */

/**
 * @param {object} p
 * @param {number} p.pg   지반 적설 하중 (psf)
 * @param {number} p.ps   지붕 설계 적설 하중 (psf)
 * @param {number} p.lu   상부 지붕 길이 (ft)
 * @param {number} p.ll   하부 지붕 길이 (ft)
 * @param {number} p.hr   단차 높이 (ft)
 * @returns {object|null}
 */
export function calcSnowDrift({ pg, ps, lu, ll, hr }) {
  // 모든 입력값이 유한한 양수여야 함 (0, 음수, NaN, Infinity 모두 거부)
  if (![pg, ps, lu, ll, hr].every(v => typeof v === 'number' && isFinite(v) && v > 0)) return null;

  // Step 1: Snow density γ — ASCE 7-10 Eq 7.7-1
  const gamma = Math.min(0.13 * pg + 14, 30); // pcf

  // Step 2: Balanced snow depth
  const hb = ps / gamma; // ft

  // Step 3: Clear height
  const hc = hr - hb; // ft

  // Step 4: Applicability — hc/hb ≥ 0.2
  const ratio = hb > 0 ? hc / hb : 0;
  const applicable = ratio >= 0.2;

  if (!applicable || hc <= 0) {
    return { applicable, ratio, gamma, hb, hc, leeward: null, windward: null, governing: null };
  }

  // Step 5: Drift heights
  const hdLeeward  = 0.43 * Math.pow(lu, 1 / 3) * Math.pow(pg + 10, 0.25) - 1.5;
  const hdWindward = 0.75 * (0.43 * Math.pow(ll, 1 / 3) * Math.pow(pg + 10, 0.25) - 1.5);

  function driftResult(hd_raw) {
    if (hd_raw <= 0) return null;
    const hd = Math.min(hd_raw, hc);
    const capped = hd_raw > hc;
    const w_raw = hd_raw <= hc ? 4 * hd : (4 * hd_raw * hd_raw) / hc;
    const w = Math.min(w_raw, 8 * hc);
    const pd = hd * gamma;
    const pmax = pd + ps;
    return { hd_raw, hd, w, pd, pmax, capped };
  }

  const leeward  = driftResult(hdLeeward);
  const windward = driftResult(hdWindward);

  const governing = (!leeward && !windward) ? null
    : (!leeward) ? windward
    : (!windward) ? leeward
    : (leeward.hd >= windward.hd ? leeward : windward);

  return {
    applicable,
    ratio,
    gamma,
    hb,
    hc,
    hdLeeward,
    hdWindward,
    leeward,
    windward,
    governing,
  };
}
